#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>
using namespace std;

string xorCipher(string text, string key) {
    for (size_t i = 0; i < text.size(); i++)
        text[i] ^= key[i % key.size()];
    return text;
}

string toHex(const string& s) {
    ostringstream oss;
    for (unsigned char c : s) oss << hex << setw(2) << setfill('0') << (int)c;
    return oss.str();
}

int main() {
    string msg = "Hello";
    string key = "key";
    string enc = xorCipher(msg, key);
    string dec = xorCipher(enc, key);
    cout << "Original: " << msg << endl;
    cout << "Encrypted (hex): " << toHex(enc) << endl;
    cout << "Decrypted: " << dec << endl;
    return 0;
}
